css:
/* THEME 8: VIBRANT TECH NEO-FUTURISM */
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;700;800&family=Syne:wght@700;800&display=swap');

:root {
  --bg-main: #0c0814;
  --bg-card: #150f24;
  --bg-header: #0c0814;
  --accent: #ccff00;
  --accent-purple: #9d4edd;
  --text-main: #ffffff;
  --text-gray: #a69ebd;
  --border-color: #271c3d;
  --font-main: 'Plus Jakarta Sans', sans-serif;
  --font-heading: 'Syne', sans-serif;
  --shadow-sm: 0 10px 30px rgba(157, 78, 221, 0.15);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body { 
  font-family: var(--font-main); 
  background-color: var(--bg-main); 
  background-image: radial-gradient(circle at 80% 20%, rgba(157, 78, 221, 0.18) 0%, transparent 40%),
                    radial-gradient(circle at 20% 80%, rgba(204, 255, 0, 0.08) 0%, transparent 40%);
  color: var(--text-gray); 
  line-height: 1.6; 
  display: flex; flex-direction: column; min-height: 100vh; 
}

a { text-decoration: none; color: inherit; transition: color 0.2s ease; }
a:hover { color: var(--accent); }

h1, h2, h3, h4 { color: var(--text-main); font-family: var(--font-heading); font-weight: 800; }

.container { max-width: 1280px; margin: 0 auto; padding: 0 24px; width: 100%; }

.site-header { 
  background: var(--bg-header); 
  border-bottom: 1px solid var(--border-color); 
  position: sticky; top: 0; z-index: 100;
}
.header-top { display: flex; justify-content: space-between; align-items: center; padding: 22px 24px; max-width: 1280px; margin: 0 auto; }
.logo { font-size: 1.8rem; font-family: var(--font-heading); font-weight: 800; color: #fff; letter-spacing: -1px; }
.logo::after { content: '✦'; color: var(--accent); margin-left: 6px; font-size: 1.2rem; }

.header-nav { background: #110b1c; border-bottom: 1px solid var(--border-color); }
.nav-links { display: flex; justify-content: center; gap: 30px; padding: 12px 20px; }
.nav-links a { color: var(--text-gray); font-size: 0.9rem; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; }
.nav-links a:hover { color: var(--accent); }

.bottom-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 28px; margin: 60px 0; }

.post-thumb-card { 
  position: relative; background: var(--bg-card); 
  border: 1px solid var(--border-color); 
  border-radius: 24px; 
  display: flex; flex-direction: column; justify-content: space-between; 
  padding: 32px; transition: all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275); 
  box-shadow: var(--shadow-sm); 
  min-height: 270px; 
}
.post-thumb-card:hover { 
  transform: translateY(-6px) scale(1.01); 
  border-color: var(--accent); 
  box-shadow: 0 15px 35px rgba(204, 255, 0, 0.15); 
}

.cat-badge { 
  background: var(--accent); 
  color: #000; padding: 6px 14px; font-size: 0.75rem; font-weight: 800; 
  border-radius: 30px; display: inline-block; margin-bottom: 20px; width: fit-content; text-transform: uppercase; 
}

.post-thumb-title { color: var(--text-main); font-size: 1.35rem; line-height: 1.35; }

.post-container { max-width: 840px; margin: 60px auto; background: var(--bg-card); padding: 50px; border-radius: 28px; border: 1px solid var(--border-color); }
.post-h1 { font-size: 3.5rem; line-height: 1.1; margin-bottom: 25px; color: #fff; }
.post-meta-info { display: flex; align-items: center; gap: 15px; padding-bottom: 25px; border-bottom: 1px solid var(--border-color); font-size: 0.95rem; margin-bottom: 35px; }
.post-meta-info img { width: 46px; height: 46px; border-radius: 12px; border: 2px solid var(--accent-purple); }
.post-content { font-size: 1.15rem; line-height: 1.8; color: #c9c2db; }
.post-content h2 { font-size: 2rem; margin: 45px 0 20px; color: var(--accent); }
.post-content p { margin-bottom: 22px; }
.post-content a { color: var(--accent); font-weight: 700; text-decoration: underline; }

.pagination { display: flex; justify-content: center; gap: 10px; margin: 40px 0 80px; }
.page-link { width: 44px; height: 44px; display: flex; justify-content: center; align-items: center; border: 1px solid var(--border-color); background: var(--bg-card); border-radius: 14px; font-weight: 700; color: #fff; }
.page-link:hover { border-color: var(--accent); color: var(--accent); }
.page-link.active { background: var(--accent); color: #000; border-color: var(--accent); }

.site-footer { background: #07040c; border-top: 1px solid var(--border-color); padding: 70px 0 30px; margin-top: auto; }
.footer-container { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 40px; max-width: 1280px; margin: 0 auto; padding: 0 24px; }
.footer-title { margin-bottom: 22px; font-family: var(--font-heading); font-size: 1.1rem; color: #fff; }
.footer-bottom { text-align: center; margin-top: 60px; padding-top: 25px; border-top: 1px solid var(--border-color); font-size: 0.85rem; color: #696080; }
